# RUN: llvm-mc -triple=powerpc-unknown-eabi -mcpu=e200z4 -mattr=+vle -show-encoding %s \
# RUN:   | FileCheck %s
# Expected encodings come from NXP GNU as 2.28 (-mvle -me200z4), generated by
# plans/e200/tools/gen_mc_test.py.
# RR-form instructions (VLEPEM Rev. 0 Figure A-7).  RX/RY name r0-r7 and
# r24-r31; ARX/ARY name r8-r23.

# CHECK: se_mr 3, 4 # encoding: [0x01,0x43]
se_mr 3, 4
# CHECK: se_mr 31, 0 # encoding: [0x01,0x0f]
se_mr 31, 0
# CHECK: se_mr 0, 24 # encoding: [0x01,0x80]
se_mr 0, 24
# CHECK: se_mtar 8, 3 # encoding: [0x02,0x30]
se_mtar 8, 3
# CHECK: se_mtar 23, 7 # encoding: [0x02,0x7f]
se_mtar 23, 7
# CHECK: se_mfar 3, 8 # encoding: [0x03,0x03]
se_mfar 3, 8
# CHECK: se_mfar 24, 23 # encoding: [0x03,0xf8]
se_mfar 24, 23
# CHECK: se_add 3, 4 # encoding: [0x04,0x43]
se_add 3, 4
# CHECK: se_mullw 3, 4 # encoding: [0x05,0x43]
se_mullw 3, 4
# CHECK: se_sub 3, 4 # encoding: [0x06,0x43]
se_sub 3, 4
# CHECK: se_subf 3, 4 # encoding: [0x07,0x43]
se_subf 3, 4
# CHECK: se_cmp 3, 4 # encoding: [0x0c,0x43]
se_cmp 3, 4
# CHECK: se_cmpl 3, 4 # encoding: [0x0d,0x43]
se_cmpl 3, 4
# CHECK: se_cmph 3, 24 # encoding: [0x0e,0x83]
se_cmph 3, 24
# CHECK: se_cmphl 3, 4 # encoding: [0x0f,0x43]
se_cmphl 3, 4
# CHECK: se_srw 3, 4 # encoding: [0x40,0x43]
se_srw 3, 4
# CHECK: se_sraw 3, 4 # encoding: [0x41,0x43]
se_sraw 3, 4
# CHECK: se_slw 3, 4 # encoding: [0x42,0x43]
se_slw 3, 4
# CHECK: se_or 3, 4 # encoding: [0x44,0x43]
se_or 3, 4
# CHECK: se_andc 3, 4 # encoding: [0x45,0x43]
se_andc 3, 4
# CHECK: se_and 3, 4 # encoding: [0x46,0x43]
se_and 3, 4
# CHECK: se_and. 3, 4 # encoding: [0x47,0x43]
se_and. 3, 4
